('0489','free-exercise-db-with-videos','45 Degree Hyperextension',array['erector spinae']::text[],array['glutes','hamstrings','lower back']::text[],'leverage machine','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/45-degree-hyperextension.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/45-degree-hyperextension.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/45-degree-hyperextension.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/45-degree-hyperextension.jpg',array['Position yourself on the 45-degree hyperextension bench with ankles secured.','Cross arms over chest or place hands behind head.','Lower your upper body forward at the hips.','Stop when your upper body is just below parallel to the floor.','Lift your torso back up in line with your legs.']::text[],'back','beginner',true,false,array['back extension','hyperextension bench','Roman chair extension','45 Degree Hyperextension','hyperextension']::text[],'A lower back exercise on a 45-degree hyperextension bench that targets the spinal erectors and posterior chain.',array['Rounding the back','Overextending at the top','Using momentum']::text[],array['Keep back straight','Hinge from hips','Engage glutes','Avoid hyperextending spine']::text[],'Exhale as you rise, inhale as you lower.',6.0),
('drv-45-degree-bycicle-twisting-crunch','free-exercise-db-with-videos','45-Degree Bicycle Twisting Crunch',array['obliques','external obliques']::text[],array['rectus abdominis','hip flexors']::text[],'body weight','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/45-degree-bycicle-twisting-crunch.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/45-degree-bycicle-twisting-crunch.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/45-degree-bycicle-twisting-crunch.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/45-degree-bycicle-twisting-crunch.jpg',array['Lie down with your hands behind your head and legs extended upwards at about a 45-degree angle.','Engage your core and lift your shoulders off the ground.','Twist your upper body, bringing your right elbow toward your left knee as you extend your right leg.','Return to the starting position and repeat to the opposite side.','Continue alternating sides in a controlled, twisting motion.']::text[],'waist','intermediate',true,false,array['bicycle crunch','twisting bicycle crunch','diagonal bicycle crunch']::text[],'A twisting crunch performed at a 45-degree angle to target the obliques and rectus abdominis.',array['Pulling on the neck','Using momentum instead of abs','Allowing hips to sag']::text[],array['Keep elbows wide','Twist through the torso','Do not pull on neck','Control each rep']::text[],'Exhale during the twist, inhale as you return to center.',5.0),
('drv-45-degree-bycicle-twisting-crunch-1','free-exercise-db-with-videos','45-Degree Bicycle Twisting Crunch',array['abdominals','rectus abdominis']::text[],array['obliques','hip flexors']::text[],'body weight','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/45-degree-bycicle-twisting-crunch-1.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/45-degree-bycicle-twisting-crunch-1.jpg',null,null,array['Lie on your back with hands behind your head and knees bent.','Lift your shoulders and feet off the ground, creating a 45-degree angle with your torso and legs.','Bring your right knee in while twisting your left elbow towards it.','Switch sides, extending the right leg and bringing the left knee in as your right elbow moves towards it.','Continue alternating sides in a smooth, controlled motion.']::text[],'waist','beginner',true,false,array['bicycle crunch','oblique twist crunch','diagonal bicycle crunch']::text[],'A twisting ab exercise performed at a 45-degree angle to target the abdominals and obliques.',array['Using momentum','Pulling on neck','Not twisting fully']::text[],array['Keep lower back pressed to ground','Twist through your torso','Avoid pulling on your neck','Move legs in a controlled fashion']::text[],'Exhale as you crunch and twist, inhale as you return to center.',5.0),
('drv-stretching-all-fours-squad-stretch','free-exercise-db-with-videos','All Fours Groin Stretch',array['adductors','adductor group']::text[],array['gluteus maximus','hamstrings']::text[],'body weight','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/stretching-all-fours-squad-stretch.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/stretching-all-fours-squad-stretch.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/stretching-all-fours-squad-stretch.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/stretching-all-fours-squad-stretch.jpg',array['Start on hands and knees (quadruped position).','Slide knees apart, keeping shins and feet in line with knees.','Lower hips toward the floor, maintaining a flat back.','Move hips back gently until you feel a stretch in the groin.','Hold the position and breathe deeply.']::text[],'hips','beginner',false,false,array['quadruped adductor stretch','all fours inner thigh stretch','all fours frog stretch']::text[],'A floor stretch on hands and knees targeting the adductors and groin area.',array['Arching lower back','Letting feet come together','Overstretching past comfort']::text[],array['Keep spine neutral','Move slowly','Avoid bouncing','Relax into stretch']::text[],'Breathe slowly and deeply throughout the stretch.',3.8),
('0970','free-exercise-db-with-videos','Band Assisted Pull-up',array['lats','biceps']::text[],array['biceps','forearms']::text[],'band','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-assisted-pull-up.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-assisted-pull-up.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-assisted-pull-up.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-assisted-pull-up.jpg',array['Loop the band securely over a pull-up bar and place one foot or knee into the bottom of the band.','Grip the bar slightly wider than shoulder width with your palms facing away from you.','Hang with straight arms, tighten your midsection, and pull your shoulders down away from your ears.','Pull yourself up by driving your elbows down and back until your chin clears the bar.','Lower yourself with control until your arms are straight again, keeping tension through your torso.']::text[],'back','intermediate',true,false,array['assisted pull-up','band pull-up','resistance band pull-up','banded pull-up','pull-up with band','band assisted pull-up']::text[],'A vertical pulling exercise using a resistance band for assistance to build pull-up strength in the lats, biceps, and upper back.',array['Kicking or swinging to get up','Shrugging shoulders up toward the ears','Stopping short with the chin below the bar','Dropping quickly to the bottom without control']::text[],array['Drive elbows to hips','Keep ribs down','Shoulders away from ears','Control the descent']::text[],'Inhale at the bottom before you pull, exhale as you pull up, and inhale again as you lower under control.',6.0),
('drv-band-bent-over-rear-lateral-raise','free-exercise-db-with-videos','Band Bent-Over Rear Lateral Raise',array['rear deltoids','posterior deltoid']::text[],array['rhoboids','trapezius','infraspinatus']::text[],'band','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-bent-over-rear-lateral-raise.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-bent-over-rear-lateral-raise.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-bent-over-rear-lateral-raise.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-bent-over-rear-lateral-raise.jpg',array['Stand on a resistance band, feet shoulder-width apart.','Hinge forward at hips, keeping back flat.','Hold band with both hands, arms hanging down.','Raise arms out to sides until parallel with shoulders.','Lower arms back down with control.']::text[],'shoulders','beginner',false,false,array['band rear delt raise','band bent-over reverse fly','band rear lateral raise']::text[],'A rear shoulder and upper back exercise using a resistance band in a bent-over position.',array['Rounding back','Shrugging shoulders','Using momentum']::text[],array['Flat back','Slight elbow bend','Squeeze shoulders','Slow control']::text[],'Exhale during the raise, inhale during the lowering.',4.5),
('3006','free-exercise-db-with-videos','Band Hip Abduction',array['gluteus medius']::text[],array['gluteus minimus','tensor fasciae latae']::text[],'band','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-hip-abduction.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-hip-abduction.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-hip-abduction.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-hip-abduction.jpg',array['Place a resistance band around your thighs or ankles.','Stand tall with feet hip-width apart.','Shift weight to one leg.','Lift the other leg laterally against band resistance.','Return leg to start; repeat on both sides.']::text[],'upper legs','beginner',false,true,array['resistance band hip abduction','banded side leg raise','band hip abductions','mini band hip abduction','Band Hip Abduction','resistance band seated hip abduction']::text[],'A lateral leg movement with a resistance band to activate and strengthen the hip abductor muscles.',array['Leaning torso','Poor balance','Letting band snap back']::text[],array['Keep chest up','Stable standing leg','Move slowly','Feel glute engagement']::text[],'Exhale as you lift leg, inhale as you return.',4.5),
('drv-band-hip-adduction','free-exercise-db-with-videos','Band Hip Adduction',array['adductors','adductor group']::text[],array['gluteus medius','quadriceps']::text[],'band','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-hip-adduction.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-hip-adduction.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-hip-adduction.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-hip-adduction.jpg',array['Secure a resistance band to a sturdy anchor at ankle height.','Loop the other end around your working ankle.','Stand tall and hold onto a support if needed.','Bring your working leg across your body, adducting at the hip.','Slowly return to the starting position and repeat.']::text[],'hips','beginner',false,true,array['resistance band hip adduction','band adductor exercise']::text[],'A resistance band exercise that strengthens the inner thigh muscles through hip adduction.',array['Using momentum','Rotating hips outward','Bending the standing leg excessively']::text[],array['Keep core tight','Move with control','Avoid swinging','Maintain upright posture']::text[],'Exhale as you pull leg inward, inhale as you return.',4.5),
('0983','free-exercise-db-with-videos','Band Kneeling One Arm Pulldown',array['lats','biceps']::text[],array['biceps','rhomboids']::text[],'band','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-kneeling-one-arm-pulldown.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-kneeling-one-arm-pulldown.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-kneeling-one-arm-pulldown.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-kneeling-one-arm-pulldown.jpg',array['Anchor the band overhead and kneel facing the anchor point.','Grab the band with one hand and extend that arm up and slightly forward.','Brace your torso and keep your chest tall without leaning back.','Pull your elbow down toward your side until your hand reaches about shoulder or rib level.','Squeeze your lat at the bottom while keeping your shoulder down.','Slowly straighten your arm back overhead under control.','Complete all reps on one side, then switch arms.']::text[],'back','beginner',true,true,array['single-arm band pulldown','kneeling single-arm band lat pulldown','one-arm band pulldown','band lat pulldown','single-arm kneeling pulldown','single-arm band lat pull','band kneeling one arm pulldown']::text[],'A kneeling single-arm band pulldown that trains the lats by pulling the elbow down from an overhead position.',array['Leaning the torso back to finish the pull','Shrugging the shoulder up toward the ear','Bending and straightening the wrist during the pull','Letting the band snap the arm back overhead']::text[],array['Drive elbow to your side','Keep ribs down','Shoulder away from your ear','Move slowly on the return']::text[],'Inhale as your arm returns overhead, and exhale as you pull the band down to your side.',6.0),
('1017','free-exercise-db-with-videos','Band One Arm Front Raise',array['anterior deltoid','deltoid anterior']::text[],array['upper pectorals','serratus anterior']::text[],'band','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-one-arm-forward-raise.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-one-arm-forward-raise.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-one-arm-forward-raise.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-one-arm-forward-raise.jpg',array['Stand with one foot on the band for resistance.','Hold handle in one hand at thigh level, palm facing down.','Keep arm straight, raise it forward to shoulder height.','Pause briefly at the top.','Lower arm back down slowly and repeat.']::text[],'shoulders','beginner',false,true,array['band single arm front raise','one arm band front raise','resistance band front raise','Band One Arm Forward Raise','band y-raise']::text[],'Isolation shoulder exercise raising one arm forward against band resistance to target the anterior deltoid.',array['Swinging the arm','Bending at the elbow','Raising above shoulder']::text[],array['Raise to shoulder height','Keep elbow soft','Don''t swing','Control the descent']::text[],'Exhale as you lift, inhale as you lower.',4.5),
('drv-band-one-leg-kickback-bent-position','free-exercise-db-with-videos','Band One-Leg Kickback (Bent Position)',array['glutes','gluteus maximus']::text[],array['hamstrings','lower back']::text[],'band','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-one-leg-kickback-bent-position.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-one-leg-kickback-bent-position.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-one-leg-kickback-bent-position.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-one-leg-kickback-bent-position.jpg',array['Anchor the band and loop it around your working ankle.','Start on all fours with hands under shoulders and knees bent.','Engage your core and extend one leg backward against band resistance.','Pause and squeeze the glute at the top.','Return to starting position and repeat for desired reps, then switch legs.']::text[],'back','beginner',false,true,array['band glute kickback','resistance band kickback','band donkey kick']::text[],'A glute-focused kickback performed from a bent-over position using a resistance band for added intensity.',array['Sagging the lower back','Rotating the hips','Using momentum']::text[],array['Keep back flat','Drive heel upward','Squeeze glutes','Avoid arching lower back']::text[],'Exhale as you kick back, inhale as you bring the knee in.',4.5),
('new-band-overhead-triceps-extension','free-exercise-db-with-videos','Band Overhead Triceps Extension',array['triceps','upper arms']::text[],array['shoulders','core']::text[],'band','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-overhead-triceps-extension.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-overhead-triceps-extension.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-overhead-triceps-extension.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-overhead-triceps-extension.jpg',array['Stand on the middle of the band with feet hip-width apart and hold one end in each hand.','Raise your hands overhead and bend your elbows so your hands move behind your head.','Keep your upper arms close to your ears and brace your midsection.','Straighten your elbows to press the band overhead until your arms are fully extended.','Pause briefly at the top, then bend your elbows slowly to return behind your head.','Repeat without letting your elbows flare wide.']::text[],'upper arms','beginner',false,false,array['band overhead triceps extension','resistance band overhead triceps extension','overhead band triceps extension','band triceps extension','band overhead extension','overhead triceps with band']::text[],'A standing band triceps exercise where you extend your elbows overhead while keeping your upper arms mostly fixed.',array['Elbows flare out to the sides','Lower back arches as the band goes overhead','Upper arms drift forward and backward','Only moving partway instead of fully extending']::text[],array['Elbows point forward','Upper arms stay still','Brace your ribs down','Fully straighten the elbows']::text[],'Inhale as you lower your hands behind your head, and exhale as you straighten your elbows overhead.',4.5),
('0976','free-exercise-db-with-videos','Band Prone Leg Curl',array['hamstrings']::text[],array['gastrocnemius','gluteus maximus']::text[],'band','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-leg-curl.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-leg-curl.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-leg-curl.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-leg-curl.jpg',array['Anchor the band securely at ground level.','Lie face down with legs extended.','Loop the band around your ankle.','Flex your knee, bringing your heel toward your glutes.','Slowly return to the start; repeat and switch legs if desired.']::text[],'upper legs','beginner',false,false,array['Resistance Band Leg Curl','Band Hamstring Curl','Lying Band Leg Curl','Band Leg Curl','band concentration curl']::text[],'A hamstring isolation exercise performed lying face down and flexing the knee using resistance from a band.',array['Lifting hips off ground','Using momentum','Letting band snap back']::text[],array['Keep hips down','Point toes away','Squeeze hamstrings at top','Control lowering phase']::text[],'Exhale as you curl, inhale as you lower.',4.5),
('0991','free-exercise-db-with-videos','Band Pull Through',array['glutes','hamstrings']::text[],array['hamstrings','lower back']::text[],'band','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-pull-through.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-pull-through.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-pull-through.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-pull-through.jpg',array['Anchor the band at floor level and loop it between your legs.','Face away from the anchor and walk forward until the band is taut.','Stand with feet about hip-width apart and soften your knees.','Push your hips back and hinge forward, letting the band travel behind you.','Lower until you feel your hamstrings stretch while keeping your back flat.','Drive your hips forward to stand tall and squeeze your glutes at the top.']::text[],'upper legs','beginner',true,false,array['band pull through','resistance band pull through','banded pull through','hip hinge with band','glute pull through']::text[],'A banded hip hinge that trains the glutes and hamstrings by pulling the band through the legs as you stand tall.',array['Squatting down instead of hinging back','Rounding the lower back as you fold forward','Letting the band pull the hips backward at lockout','Bending the knees too much and shifting into the quads']::text[],array['Push hips back','Keep ribs down','Stand tall at top','Squeeze glutes hard']::text[],'Inhale as you hinge back and exhale as you drive your hips forward to stand.',6.0),
('drv-band-decline-sit-ups','free-exercise-db-with-videos','Band Resisted Decline Sit-Up',array['rectus abdominis']::text[],array['hip flexors','obliques']::text[],'band','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/band-decline-sit-ups.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/band-decline-sit-ups.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/band-decline-sit-ups.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/band-decline-sit-ups.jpg',array['Attach a resistance band securely behind the decline bench.','Lie on the bench with your feet anchored, holding the band at the chest or behind the neck.','Engage your core and perform a sit-up, raising your torso towards your knees.','Control the movement back down to starting position.','Repeat for the desired repetitions.']::text[],'waist','intermediate',false,false,array['band decline sit-up','decline sit-up with band','resisted decline sit-up']::text[],'A decline sit-up performed with band resistance to increase tension on the abdominals.',array['Using momentum','Letting band go slack','Improper anchoring of feet']::text[],array['Keep tension in band','Crunch up slowly','Avoid swinging','Exhale on exertion']::text[],'Exhale as you sit up, inhale as you lower down.',4.5),
