('0493','free-exercise-db-with-videos','Incline Push-Up',array['pectorals','pectoralis major']::text[],array['anterior deltoids','triceps']::text[],'body weight','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/incline-push-ups.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/incline-push-ups.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/incline-push-ups.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/incline-push-ups.jpg',array['Place hands shoulder-width apart on elevated surface.','Extend legs back with feet together, forming a straight line.','Lower chest toward the surface, elbows at 45 degrees.','Pause when chest is just above the surface.','Push back up to starting position.']::text[],'chest','beginner',true,false,array['elevated push-up','bench push-up','hands elevated push-up','Incline Push-Ups','incline push-up']::text[],'A push-up variation with hands elevated, reducing resistance on the chest and triceps.',array['Sagging hips','Flaring elbows out','Incomplete range of motion']::text[],array['Maintain straight line body','Core engaged','Lower under control','Exhale as you push up']::text[],'Inhale as you lower, exhale as you push up.',5.0),
