('drv-jack-split-crunches','free-exercise-db-with-videos','Jackknife Split Crunch',array['rectus abdominis']::text[],array['hip flexors','obliques','adductors']::text[],'body weight',null,null,'https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/jack-split-crunches.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/jack-split-crunches.jpg',array['Lie on your back with arms extended overhead and legs straight.','Engage your core and simultaneously lift your torso and legs off the ground.','As you rise, spread your legs into a split while reaching your hands toward your feet.','Pause at the top, squeezing your abs.','Lower your legs and torso back to the ground with control, bringing feet together.']::text[],'waist','intermediate',true,false,array['jack split crunch','split jackknife crunch','jackknife crunch with split','split jack crunch']::text[],'A crunch variation combining a V-up with a leg split to target the abs and hip flexors.',array['Swinging the legs','Using momentum','Arching the lower back']::text[],array['Keep core tight','Don''t arch lower back','Lead with chest','Controlled split']::text[],'Exhale when crunching up, inhale when lowering down.',5.0),
('2612','free-exercise-db-with-videos','Jump Rope',array['cardiovascular system','calves']::text[],array['calves','quadriceps','hamstrings','glutes']::text[],'rope','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/jump-rope.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/jump-rope.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/jump-rope.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/jump-rope.jpg',array['Hold a handle in each hand with the rope behind your heels.','Stand tall with feet close together and elbows tucked by your sides.','Turn the rope with your wrists and swing it up overhead.','Hop just high enough to clear the rope as it passes under your feet.','Land softly on the balls of your feet with knees slightly bent.','Keep the rope moving in a smooth rhythm and repeat each jump.']::text[],'cardio','beginner',true,false,array['skipping rope','rope skipping','jumping rope','skip rope','basic rope jumps','jump rope']::text[],'A cardio exercise where you turn a rope with your hands and perform repeated small jumps as it passes under your feet.',array['Swinging the arms in big circles instead of using the wrists','Jumping too high off the floor on each rep','Landing flat-footed or with stiff knees','Letting the hands drift wide away from the hips']::text[],array['Turn with the wrists','Stay light on your feet','Jump only as needed','Keep elbows close']::text[],'Breathe steadily and naturally, exhaling softly every few jumps while keeping a relaxed rhythm.',8.0),
('drv-jump-step-up','free-exercise-db-with-videos','Jump Step-Up',array['quadriceps','quadriceps femoris']::text[],array['gluteus maximus','hamstrings','calves']::text[],'body weight','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/male/jump-step-up.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/male/jump-step-up.jpg','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-videos/female/jump-step-up.mp4','https://pub-585d42eb1aa64a67aedf483ec328d3fe.r2.dev/exercise-posters/female/jump-step-up.jpg',array['Stand facing a sturdy box or platform.','Place one foot firmly on top of the box.','Drive through the heel and explode upward, lifting your other knee high.','Land softly on the box with both feet.','Step or jump down with control and repeat.']::text[],'upper legs','intermediate',true,true,array['plyometric step-up','explosive step-up','box jump step-up']::text[],'A plyometric exercise involving stepping and jumping onto a raised surface to build leg power and coordination.',array['Letting the knee cave inward','Landing hard or flat-footed','Not using full range of motion']::text[],array['Drive explosively through the lead leg','Land softly','Keep chest lifted','Use arms for balance']::text[],'Exhale during the jump, inhale as you land and reset.',5.0),
